  grid-template-columns: 15px minmax(0, 1fr);
  gap: 10px;
}

.drawer-stream-marker {
  width: 11px;
  height: 11px;
  margin-top: 17px;
  border: 3px solid rgba(46, 155, 203, 0.18);
  border-radius: 50%;
  background: var(--blue);
  box-shadow: 0 0 0 4px rgba(46, 155, 203, 0.06);
}

.drawer-stream-body {
  min-width: 0;
  padding: 13px 14px;
  border: 1px solid rgba(167, 205, 222, 0.46);
  border-radius: 12px;
  background: #FFFFFF;
}

.drawer-stream-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.drawer-stream-head > div {
  min-width: 0;
}

.drawer-stream-head span {
  display: block;
  color: var(--blue);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.drawer-stream-head strong {
  display: block;
  margin-top: 2px;
  color: var(--ink);
