@media (max-width: 1050px) {
  .drawer-stat-grid,
  .drawer-stat-grid.wide {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .drawer-analysis-grid.two,
  .drawer-profile-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 700px) {
  .query-drawer-tab {
    min-height: 40px;
    padding: 0 11px;
    font-size: 13px;
  }
  .query-drawer-title-row h2 {
    font-size: 26px;
  }
  .query-drawer-post-copy,
  .drawer-stream-body > p,
  .drawer-analysis-header p {
    font-size: 14px;
  }
  .drawer-stat-grid,
  .drawer-stat-grid.wide {
    grid-template-columns: 1fr;
  }
  .drawer-source-row {
    grid-template-columns: 1fr;
  }
  .drawer-profile-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .drawer-stream-head {
    flex-direction: column;
  }
  .drawer-stream-open {
    margin-left: 0;
  }
}

