.manual-rule-row {
  min-width: 0;

  padding: 16px;

  border-right:
    1px solid var(--line-soft);
}

.manual-rule-row:last-child {
  border-right: 0;
}

.manual-rule-copy {
  min-height: 76px;
}

.manual-rule-badge {
  display: inline-flex;

  margin-bottom: 7px;

  padding: 5px 8px;

  border-radius: 7px;

  font-size: 9px;
  font-weight: 800;
}

.manual-rule-badge.include {
  color: var(--blue);

  background:
    rgba(41, 114, 169, 0.09);
}

.manual-rule-badge.and {
  color: #2582A7;

  background:
    rgba(46, 155, 203, 0.10);
}

.manual-rule-badge.exclude {
  color: #8E4E4E;

  background:
    rgba(169, 92, 92, 0.09);
}

.manual-rule-copy strong {
  display: block;

  margin-bottom: 4px;

  font-size: 11.5px;
}

.manual-rule-copy p {
  color: var(--muted);

  font-size: 10px;
  line-height: 1.5;
}

.manual-term-entry {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    auto;

  gap: 7px;
}

.manual-term-input {
  width: 100%;
  min-width: 0;
  height: 38px;

  padding: 0 11px;

  border:
    1px solid var(--line);

  border-radius: 9px;

  outline: none;

  background: #FBFDFE;

  font-size: 10px;
}

.ai-instruction-input {
  height: 132px;
  min-height: 132px;

  padding: 10px 11px;

  line-height: 1.5;
  resize: vertical;
}

.manual-add-term {
  min-width: 70px;
  height: 38px;

  padding: 0 10px;

  border:
    1px solid
    rgba(41, 114, 169, 0.18);

  border-radius: 9px;

  background:
    rgba(41, 114, 169, 0.07);

  color: var(--blue);

  font-size: 9px;
  font-weight: 700;

  cursor: pointer;
}

.manual-term-list {
  min-height: 42px;

  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;

  gap: 6px;

  margin-top: 7px;
  padding: 7px;

  border-radius: 9px;

  background:
    rgba(167, 205, 222, 0.07);
}

.manual-empty-terms {
  color: var(--muted-soft);

  font-size: 9px;
}

.manual-chip {
  display: inline-flex;
  align-items: center;

  gap: 6px;

  min-height: 27px;

  padding: 0 5px 0 9px;

  border-radius: 8px;

  color: var(--blue);

  background:
    rgba(41, 114, 169, 0.10);

  font-size: 10px;
  font-weight: 600;
}

.manual-chip-remove {
  width: 18px;
  height: 18px;

  border: 0;
  border-radius: 50%;

  cursor: pointer;
}

.manual-group-footer {
  padding-top: 10px;
}

.manual-add-group {
  width: 100%;
  height: 38px;

  border:
    1px dashed
    rgba(41, 114, 169, 0.35);

  border-radius: 9px;

  background: transparent;

  color: var(--blue);

  font-size: 10px;
  font-weight: 700;

  cursor: pointer;
}

.manual-stage-summary,
.manual-source-summary {
  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 14px;

  margin-top: 12px;

  padding: 10px 12px;

  border:
    1px solid var(--line-soft);

  border-radius: 10px;

  background:
    rgba(167, 205, 222, 0.06);

  font-size: 10px;
}

.manual-stage-summary strong,
.manual-source-summary strong {
  color: var(--blue);
}


/* MANUAL PASO 2 */

.manual-sources-section,
.manual-web-section {
  padding: 16px;

  border:
    1px solid var(--line);

  border-radius: 14px;

  background:
    linear-gradient(
      180deg,
      #FFFFFF,
      #FBFDFE
    );
}

.manual-web-section {
  margin-top: 12px;
}

.manual-sources-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 12px;

  margin-bottom: 12px;
}

.manual-sources-heading span {
  display: block;

  margin-bottom: 2px;

  color: var(--blue);

  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-sources-heading strong {
  display: block;

  font-size: 12px;
}

.manual-sources-heading small {
  color: var(--muted);

  font-size: 9px;
}

.manual-source-grid {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 10px;
}

.manual-web-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 1fr);

  gap: 10px;
}

.manual-source-card {
  position: relative;

  min-height: 94px;

  display: flex;
  align-items: center;

  gap: 11px;

  padding: 13px;

  border:
    1px solid var(--line);

  border-radius: 12px;

  background:
    #FFFFFF;

  text-align: left;

  cursor: pointer;

  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease;
}

.manual-source-card:hover {
  border-color:
    rgba(41, 114, 169, 0.36);
}

.manual-source-card.selected {
  border-color:
    rgba(41, 114, 169, 0.62);

  background:
    rgba(41, 114, 169, 0.055);

  box-shadow:
    0 0 0 2px
    rgba(41, 114, 169, 0.05);
}

.manual-source-card.unavailable {
  opacity: 0.48;
  cursor: default;
}

.manual-source-icon {
  width: 38px;
  height: 38px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 10px;

  background:
    rgba(46, 155, 203, 0.10);

  color: var(--blue);

  font-size: 14px;
  font-weight: 800;
}

.manual-source-content {
  min-width: 0;

  display: flex;
  flex-direction: column;

  flex: 1;
}

.manual-source-platform {
  margin-bottom: 2px;

  color: var(--blue);

  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
}

.manual-source-content strong {
  overflow: hidden;

  color: var(--ink);

  font-size: 11px;
  font-weight: 700;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.manual-source-status,
.manual-source-description {
  margin-top: 4px;

  color: var(--muted);

  font-size: 9px;
}

.manual-status-dot {
  width: 6px;
  height: 6px;

  display: inline-block;

  margin-right: 4px;

  border-radius: 50%;
}

.manual-status-dot.active {
  background: var(--success);
}

.manual-status-dot.inactive {
  background: var(--muted-soft);
}

.manual-source-check {
  width: 23px;
  height: 23px;

  display: flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border:
    1px solid var(--line);

  border-radius: 7px;

  background: #FFFFFF;

  color: #FFFFFF;

  font-size: 11px;
  font-weight: 800;
}

.manual-source-card.selected
.manual-source-check {
  border-color: var(--blue);

  background: var(--blue);
}

.manual-source-switch {
  width: 40px;
  height: 23px;

  display: flex;
  align-items: center;

  flex-shrink: 0;

  padding: 2px;

  border-radius: 999px;

  background:
    rgba(113, 121, 131, 0.20);

  transition:
    background 0.18s ease;
}

.manual-source-switch span {
  width: 19px;
  height: 19px;

  display: block;

  border-radius: 50%;

  background: #FFFFFF;

  box-shadow:
    0 2px 4px
    rgba(47, 50, 59, 0.12);

  transition:
    transform 0.18s ease;
}

.manual-source-switch.active {
  background:
    linear-gradient(
      135deg,
      var(--blue),
      var(--cyan)
    );
}

.manual-source-switch.active span {
  transform:
    translateX(17px);
}

.manual-source-empty {
  grid-column: 1 / -1;

  min-height: 100px;

  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;

  padding: 20px;

  border:
    1px dashed var(--line);

  border-radius: 12px;

  text-align: center;
}

.manual-source-empty strong {
  margin-bottom: 4px;

  font-size: 11px;
}

.manual-source-empty span {
  color: var(--muted);

  font-size: 9px;
}

.manual-source-summary > div {
  display: flex;
  align-items: center;

  gap: 7px;
}

.manual-source-summary-icon {
  width: 22px;
  height: 22px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 50%;

  background:
    rgba(44, 154, 117, 0.10);

  color: var(--success);

  font-weight: 800;
}


/* ACTIONS */

.stage-actions {
  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 12px;

  margin-top: 18px;

  padding-top: 14px;

  border-top:
    1px solid var(--line-soft);
}

.stage-actions-right {
  display: flex;
  gap: 8px;
}

.stage-button {
  min-width: 120px;
  height: 40px;

  padding: 0 15px;

  border-radius: 10px;

  font-size: 10.5px;
  font-weight: 700;

  cursor: pointer;
}

.stage-button.secondary {
  border:
    1px solid var(--line);

  background: #FFFFFF;

  color: var(--blue);
}

.stage-button.primary {
  border: 0;

  background:
    linear-gradient(
      135deg,
      var(--blue),
      var(--cyan)
    );

  color: #FFFFFF;
}

.stage-button:disabled {
  opacity: 0.45;
  cursor: default;
}


/* LIBRARY */

.constructor-library {
  position: static;
  top: auto;

  padding: 18px;

  border:
    1px solid var(--line);

  border-radius: 18px;

  background:
    rgba(255, 255, 255, 0.95);
}

.library-heading {
  display: flex;
  justify-content: space-between;

  gap: 12px;

  margin-bottom: 15px;

  padding-bottom: 14px;

  border-bottom:
    1px solid var(--line-soft);
}

.library-kicker {
  display: block;

  margin-bottom: 4px;

  color: var(--blue);

  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.library-heading h2 {
  margin-bottom: 4px;

  font-family: "Playfair Display", serif;
  font-size: 19px;
}

.library-heading p {
  color: var(--muted);

  font-size: 10px;
}

.library-count {
  min-width: 30px;
  height: 30px;

  display: flex;
  align-items: center;
  justify-content: center;

  border-radius: 9px;

  background:
    rgba(41, 114, 169, 0.08);

  color: var(--blue);

  font-size: 11px;
  font-weight: 800;
}

.query-library-list {
  display: grid;

  grid-template-columns:
    repeat(
      auto-fill,
      minmax(280px, 340px)
    );

  justify-content: start;
  align-items: stretch;

  gap: 14px;

  min-height: 300px;
}

.saved-query-card {
  width: 100%;
  min-width: 0;
  min-height: 248px;

  display: flex;
  flex-direction: column;

  padding: 15px;

  border:
    1px solid var(--line);

  border-radius: 16px;

  background:
    linear-gradient(
      180deg,
      #FFFFFF 0%,
      #FBFDFE 100%
    );

  box-shadow:
    0 8px 20px
    rgba(47, 50, 59, 0.045);

  cursor: pointer;

  transition:
    border-color 0.18s,
    box-shadow 0.18s,
    transform 0.18s,
    background 0.18s;
}

.saved-query-card:hover {
  transform:
    translateY(-2px);

  border-color:
    rgba(46, 155, 203, 0.48);

  box-shadow:
    0 12px 26px
    rgba(47, 50, 59, 0.075);
}

.saved-query-card[aria-pressed="true"] {
  border-color:
    rgba(46, 155, 203, 0.62);

  background:
    linear-gradient(
      180deg,
      #FFFFFF 0%,
      rgba(223, 243, 251, 0.34) 100%
    );

  box-shadow:
    0 10px 24px
    rgba(41, 114, 169, 0.09);
}

.saved-query-card-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;

  gap: 10px;

  margin-bottom: 11px;
}

.saved-query-title {
  min-width: 0;

  display: flex;
  flex-direction: column;
}

.saved-query-title strong {
  overflow: hidden;

  color: var(--ink);

  font-size: 14px;
  font-weight: 700;
  line-height: 1.25;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.saved-query-title span {
  margin-top: 2px;

  color: var(--muted-soft);

  font-size: 10px;
}

.saved-query-status {
  height: 21px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  padding: 4px 8px;

  border-radius: 999px;

  font-size: 10px;
  font-weight: 700;
}

.saved-query-status.active {
  color: #23775C;

  background:
    rgba(44, 154, 117, 0.10);
}

.saved-query-status.inactive {
  color: #777D85;

  background:
    rgba(115, 121, 130, 0.08);
}

.saved-query-formula {
  min-height: 70px;
  max-height: 70px;

  display: -webkit-box;

  overflow: hidden;

  margin-bottom: 11px;

  padding: 9px 10px;

  border:
    1px solid var(--line-soft);

  border-radius: 9px;

  background:
    rgba(167, 205, 222, 0.08);

  color: var(--ink-soft);

  font-family: monospace;

  font-size: 10.5px;
  line-height: 1.5;

  overflow-wrap: anywhere;

  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.saved-query-metrics {
  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 6px;

  margin-top: auto;
  margin-bottom: 10px;
}

.saved-query-metrics span {
  min-width: 0;

  padding: 7px 4px;

  border-radius: 8px;

  background: var(--surface);

  color: var(--muted);

  font-size: 9.5px;
  line-height: 1.25;

  text-align: center;
}

.saved-query-metrics strong {
  display: block;

  margin-bottom: 1px;

  color: var(--blue);

  font-size: 13px;
}

.saved-query-footer {
  min-height: 34px;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 8px;

  padding-top: 9px;

  border-top:
    1px solid var(--line-soft);

  color: var(--muted);

  font-size: 10.5px;
}

.saved-query-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;

  gap: 6px;

  flex-wrap: wrap;
}

.saved-query-actions .stage-button {
  min-width: 0;
  height: 30px;

  padding:
    0 10px;

  border-radius: 8px;

  font-size: 10.5px;
}

.saved-query-actions .saved-query-status {
  height: 20px;

  padding:
    3px 7px;

  font-size: 9.5px;
}

.library-empty {
  grid-column:
    1 / -1;
}

.library-empty {
  min-height: 280px;

  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;

  border:
    1px dashed var(--line);

  border-radius: 12px;

  text-align: center;
}

.empty-pulse {
  width: 38px;
  height: 38px;

  margin-bottom: 12px;

  border-radius: 11px;

  background:
    rgba(41, 114, 169, 0.10);
}

.library-empty strong {
  margin-bottom: 4px;

  font-size: 11px;
}

.library-empty span {
  color: var(--muted);

  font-size: 9px;
}

.library-pagination {
  display: flex;
  justify-content: space-between;
  align-items: center;

  gap: 8px;

  margin-top: 12px;

  padding-top: 12px;

  border-top:
    1px solid var(--line-soft);
}

.library-pagination button {
  width: 31px;
  height: 31px;

  border:
    1px solid var(--line);

  border-radius: 8px;

  background: #FFFFFF;

  color: var(--blue);
}

.library-pagination button:disabled {
  opacity: 0.35;
}

.library-pagination span {
  color: var(--muted);

  font-size: 9px;
  font-weight: 600;
}



/* =========================================================
   FUENTES
   ========================================================= */

.sources-layout {
  display: grid;
  grid-template-columns: 1fr;

  gap: 14px;
}

.sources-panel {
  min-width: 0;

  padding: 18px;

  border: 1px solid var(--line);
  border-radius: 18px;

  background:
    rgba(255, 255, 255, 0.96);

  box-shadow:
    0 8px 22px
    rgba(47, 50, 59, 0.045);
}

.sources-panel-heading,
.sources-list-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;

  gap: 14px;

  margin-bottom: 15px;
}

.sources-panel-kicker {
  display: block;

  margin-bottom: 4px;

  color: var(--cyan);

  font-size: 8px;
  font-weight: 700;

  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.sources-panel-heading h2,
.sources-list-header h2 {
  color: var(--ink);

  font-family:
    "Playfair Display",
    serif;

  font-size: 19px;
}

.sources-panel-heading p,
.sources-list-header p {
  max-width: 680px;

  margin-top: 4px;

  color: var(--muted);

  font-size: 10px;
  line-height: 1.55;
}

.sources-count {
  min-width: 32px;
  height: 32px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  padding: 0 8px;

  border-radius: 9px;

  background:
    rgba(41, 114, 169, 0.08);

  color: var(--blue);

  font-size: 11px;
  font-weight: 800;
}

.sources-form {
  display: grid;

  grid-template-columns:
    minmax(150px, 0.75fr)
    minmax(180px, 1fr)
    minmax(200px, 1.1fr)
    auto;

  gap: 10px;

  align-items: end;
}

.sources-field {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 6px;
}

.sources-field > span {
  color: var(--muted);

  font-size: 8px;
  font-weight: 700;

  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.sources-control {
  width: 100%;
  height: 40px;

  padding: 0 11px;

  border: 1px solid var(--line);
  border-radius: 10px;

  outline: 0;

  background:
    #FBFDFE;

  color: var(--ink);

  font-size: 10px;

  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    background 0.18s ease;
}

.sources-control:focus {
  border-color:
    rgba(41, 114, 169, 0.58);

  background:
    #FFFFFF;

  box-shadow:
    0 0 0 3px
    rgba(41, 114, 169, 0.07);
}

.sources-create-button {
  min-width: 140px;
  height: 40px;

  padding: 0 15px;

  border: 0;
  border-radius: 10px;

  background:
    linear-gradient(
      135deg,
      var(--blue),
      var(--cyan)
    );

  color: #FFFFFF;

  font-size: 10px;
  font-weight: 700;

  cursor: pointer;

  box-shadow:
    0 7px 16px
    rgba(41, 114, 169, 0.14);
}

.sources-create-button:hover {
  background:
    linear-gradient(
      135deg,
      var(--blue-dark),
      var(--blue)
    );
}

.sources-toolbar {
  display: grid;

  grid-template-columns:
    minmax(220px, 1fr)
    minmax(150px, 210px)
    minmax(135px, 180px);

  gap: 8px;

  margin-bottom: 12px;
}

.sources-search {
  min-width: 0;
  height: 39px;

  display: flex;
  align-items: center;

  gap: 7px;

  padding: 0 11px;

  border: 1px solid var(--line);
  border-radius: 10px;

  background: #FFFFFF;
}

.sources-search > span {
  flex-shrink: 0;

  color: var(--blue);

  font-size: 13px;
}

.sources-search input {
  width: 100%;
  min-width: 0;

  border: 0;
  outline: 0;

  background: transparent;

  color: var(--ink);

  font-size: 10px;
}

.sources-search input::placeholder {
  color: var(--muted-soft);
}

.sources-filter {
  width: 100%;
  height: 39px;

  padding: 0 10px;

  border: 1px solid var(--line);
  border-radius: 10px;

  outline: 0;

  background: #FFFFFF;

  color: var(--ink);

  font-size: 9.5px;
  font-weight: 600;

  cursor: pointer;
}

.sources-table-wrap {
  min-width: 0;

  overflow-x: auto;

  border: 1px solid var(--line);
  border-radius: 13px;

  background: #FFFFFF;
}

.sources-table {
  width: 100%;

  border-collapse: collapse;

  font-size: 10px;
}

.sources-table th {
  padding: 10px 12px;

  border-bottom: 1px solid var(--line);

  background:
    rgba(167, 205, 222, 0.07);

  color: var(--muted);

  font-size: 8px;
  font-weight: 700;

  text-align: left;
  text-transform: uppercase;

  letter-spacing: 0.08em;

  white-space: nowrap;
}

.sources-table td {
  padding: 11px 12px;

  border-bottom:
    1px solid var(--line-soft);

  color: var(--ink);

  vertical-align: middle;
}

.sources-table tbody tr:last-child td {
  border-bottom: 0;
}

.sources-table tbody tr:hover {
  background:
    rgba(167, 205, 222, 0.07);
}

.sources-platform {
  display: inline-flex;
  align-items: center;

  gap: 7px;

  color: var(--blue);

