/* =========================================================
   DRAWER DE RESULTADOS DE CONSULTA — ALERT INSPIRED
   ========================================================= */

body.query-drawer-open {
  overflow: hidden;
}

.query-drawer-overlay {
  position: fixed;
  inset: 0;

  z-index: 1000;

  display: flex;
  justify-content: flex-end;

  overflow: hidden;
}

.query-drawer-backdrop {
  position: absolute;
  inset: 0;

  width: 100%;
  height: 100%;

  border: 0;

  background:
    rgba(28, 35, 48, 0.46);

  backdrop-filter:
    blur(2px);

  cursor: pointer;

  opacity: 0;

  transition:
    opacity 0.24s ease;
}

.query-drawer {
  position: relative;
  z-index: 1;

  width: min(84%, 1420px);
  height: 100%;

  display: flex;
  flex-direction: column;

  overflow: hidden;

  border-left:
    1px solid rgba(167, 205, 222, 0.82);

  background:
    linear-gradient(
      180deg,
      #F8FBFD 0%,
      #F4F8FB 52%,
      #F8FBFD 100%
    );

  box-shadow:
    -26px 0 64px
    rgba(24, 37, 51, 0.24);

  transform:
    translateX(100%);

  transition:
    transform 0.24s ease;
}

.query-drawer-overlay.open
.query-drawer-backdrop {
  opacity: 1;
}

.query-drawer-overlay.open
.query-drawer {
  transform:
    translateX(0);
}


/* HEADER */

.query-drawer-header {
  flex-shrink: 0;

  display: flex;
  align-items: center;
  justify-content: space-between;

  gap: 24px;

  min-height: 90px;

  padding:
    16px 22px 14px;

  border-bottom:
    1px solid rgba(167, 205, 222, 0.44);

  background:
    rgba(255, 255, 255, 0.985);
}

.query-drawer-heading {
  min-width: 0;
  flex: 1;
}

