  align-items: center;

  gap: 8px;

  margin-bottom: 8px;
}

.query-drawer-kicker {
  color: var(--cyan);

  font-size: 7.5px;
  font-weight: 800;

  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.query-drawer-status {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 21px;

  padding:
    0 8px;

  border:
    1px solid rgba(44, 154, 117, 0.16);

  border-radius: 999px;

  background:
    rgba(44, 154, 117, 0.09);

