  display: flex;
  align-items: center;

  gap: 10px;
}

.query-drawer-query-mark {
  width: 34px;
  height: 34px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border:
    1px solid rgba(46, 155, 203, 0.18);

