  font-weight: 650;
}


/* TAB CONTROLS */

.query-drawer-tab-control {
  position: absolute;

  width: 1px;
  height: 1px;

  overflow: hidden;

  clip: rect(0 0 0 0);
  clip-path: inset(50%);

  white-space: nowrap;
}

.query-drawer-tabs {
  flex-shrink: 0;

  display: flex;
  align-items: center;

  gap: 1px;

  overflow-x: auto;

  padding:
    7px 18px 6px;

  border-bottom:
    1px solid rgba(167, 205, 222, 0.42);

  background:
    #FFFFFF;

  scrollbar-width: thin;
}

.query-drawer-tab {
  position: relative;

  min-height: 34px;

  display: inline-flex;
  align-items: center;

  gap: 5px;

  padding:
    0 9px;

  flex-shrink: 0;

  border-radius: 8px;

  background:
    transparent;

  color: var(--muted);

  font-size: 8.5px;
  font-weight: 700;

  cursor: pointer;

  user-select: none;

  transition:
    color 0.18s,
    background 0.18s;
}

.query-drawer-tab::after {
  content: "";

  position: absolute;
  left: 9px;
  right: 9px;
  bottom: -7px;

  height: 2px;

  border-radius: 999px;

  background:
    linear-gradient(
      90deg,
      var(--blue),
      var(--cyan)
    );

  opacity: 0;

  transform:
    scaleX(0.55);

  transition:
    opacity 0.18s,
    transform 0.18s;
}

.query-drawer-tab:hover {
  background:
    rgba(167, 205, 222, 0.10);

  color: var(--blue);
}

.query-drawer-tab-icon {
  width: 16px;
  height: 16px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  color: currentColor;

  font-size: 9px;
  line-height: 1;
}

#queryDrawerTab-live:checked ~ .query-drawer-tabs label[for="queryDrawerTab-live"],
#queryDrawerTab-what:checked ~ .query-drawer-tabs label[for="queryDrawerTab-what"],
#queryDrawerTab-when:checked ~ .query-drawer-tabs label[for="queryDrawerTab-when"],
#queryDrawerTab-howmuch:checked ~ .query-drawer-tabs label[for="queryDrawerTab-howmuch"],
#queryDrawerTab-how:checked ~ .query-drawer-tabs label[for="queryDrawerTab-how"],
#queryDrawerTab-who:checked ~ .query-drawer-tabs label[for="queryDrawerTab-who"],
#queryDrawerTab-where:checked ~ .query-drawer-tabs label[for="queryDrawerTab-where"],
#queryDrawerTab-profiles:checked ~ .query-drawer-tabs label[for="queryDrawerTab-profiles"],
#queryDrawerTab-botometer:checked ~ .query-drawer-tabs label[for="queryDrawerTab-botometer"],
#queryDrawerTab-streams:checked ~ .query-drawer-tabs label[for="queryDrawerTab-streams"] {
  background:
    rgba(41, 114, 169, 0.08);

  color: var(--blue);
}

#queryDrawerTab-live:checked ~ .query-drawer-tabs label[for="queryDrawerTab-live"]::after,
#queryDrawerTab-what:checked ~ .query-drawer-tabs label[for="queryDrawerTab-what"]::after,
#queryDrawerTab-when:checked ~ .query-drawer-tabs label[for="queryDrawerTab-when"]::after,
#queryDrawerTab-howmuch:checked ~ .query-drawer-tabs label[for="queryDrawerTab-howmuch"]::after,
#queryDrawerTab-how:checked ~ .query-drawer-tabs label[for="queryDrawerTab-how"]::after,
#queryDrawerTab-who:checked ~ .query-drawer-tabs label[for="queryDrawerTab-who"]::after,
#queryDrawerTab-where:checked ~ .query-drawer-tabs label[for="queryDrawerTab-where"]::after,
#queryDrawerTab-profiles:checked ~ .query-drawer-tabs label[for="queryDrawerTab-profiles"]::after,
#queryDrawerTab-botometer:checked ~ .query-drawer-tabs label[for="queryDrawerTab-botometer"]::after,
#queryDrawerTab-streams:checked ~ .query-drawer-tabs label[for="queryDrawerTab-streams"]::after {
  opacity: 1;

  transform:
    scaleX(1);
}

.query-drawer-tab-control:focus-visible ~ .query-drawer-tabs .query-drawer-tab {
  outline: none;
}

#queryDrawerTab-live:focus-visible ~ .query-drawer-tabs label[for="queryDrawerTab-live"],
#queryDrawerTab-what:focus-visible ~ .query-drawer-tabs label[for="queryDrawerTab-what"],
#queryDrawerTab-when:focus-visible ~ .query-drawer-tabs label[for="queryDrawerTab-when"],
#queryDrawerTab-howmuch:focus-visible ~ .query-drawer-tabs label[for="queryDrawerTab-howmuch"],
#queryDrawerTab-how:focus-visible ~ .query-drawer-tabs label[for="queryDrawerTab-how"],
#queryDrawerTab-who:focus-visible ~ .query-drawer-tabs label[for="queryDrawerTab-who"],
#queryDrawerTab-where:focus-visible ~ .query-drawer-tabs label[for="queryDrawerTab-where"],
