.query-drawer-post-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;

  gap: 8px;
}

.query-drawer-post-source {
  min-width: 0;

  display: flex;
  align-items: center;
  flex-wrap: wrap;

  gap: 5px;
}

.query-drawer-post-platform {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 24px;

  padding:
    0 8px;

  flex-shrink: 0;

  border-radius: 7px;

  background:
    rgba(46, 155, 203, 0.10);

  color: var(--blue);

  font-size: 7px;
  font-weight: 800;

  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.query-drawer-post-handle {
  min-width: 0;
  max-width: 150px;

  overflow: hidden;

  color: var(--ink-soft);

  font-size: 8px;
  font-weight: 750;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-post-date {
  flex-shrink: 0;

  color: var(--muted-soft);

  font-size: 7px;
  font-weight: 650;
}

.query-drawer-post-copy {
  display: -webkit-box;

  margin-top: 10px;

  overflow: hidden;

  color: #3D424B;

  font-size: 9px;
  line-height: 1.55;

  word-break: break-word;

  -webkit-box-orient: vertical;
  -webkit-line-clamp: 5;
}

.query-drawer-post-copy > span {
  color: var(--muted-soft);
}

.query-drawer-post-footer {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;

  gap: 8px;

  margin-top: auto;
  padding-top: 10px;

  border-top:
    1px solid rgba(167, 205, 222, 0.22);
}

.query-drawer-post-metrics {
  min-width: 0;

  display: flex;
  align-items: center;
  flex-wrap: wrap;

  gap: 4px;
}

.query-drawer-metric {
  min-height: 22px;

  display: inline-flex;
  align-items: center;

  gap: 3px;

  padding:
    0 6px;

  border-radius: 6px;

  background:
    rgba(167, 205, 222, 0.10);

  color: var(--muted);

  font-size: 6.7px;
  font-weight: 600;
}

.query-drawer-metric strong {
  color: var(--ink-soft);

  font-size: 7.2px;
  font-weight: 800;
}

.query-drawer-metric:nth-child(5) {
  font-size: 0;
}

.query-drawer-metric:nth-child(5)::before {
  content: "Persistidos";

  color: var(--muted);

  font-size: 6.7px;
  font-weight: 600;
}

.query-drawer-metric:nth-child(5) strong {
  margin-left: 3px;
}

.query-drawer-post-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;

  min-height: 25px;

  padding:
    0 8px;

  flex-shrink: 0;

  border:
    1px solid rgba(41, 114, 169, 0.14);

  border-radius: 7px;

  background:
    rgba(41, 114, 169, 0.055);

  color: var(--blue);

  font-size: 7.5px;
  font-weight: 750;

  text-decoration: none;
}

.query-drawer-post-link:hover {
  border-color:
    rgba(41, 114, 169, 0.28);

  background:
    rgba(41, 114, 169, 0.09);
}


/* LIVE ANALYTICS */

.query-drawer-live-side {
  min-width: 0;

  display: flex;
  flex-direction: column;

  gap: 10px;
}

.query-drawer-kpi-grid {
  display: grid;

  grid-template-columns:
    minmax(0, 0.72fr)
    minmax(0, 1.28fr);

  gap: 8px;
}

.query-drawer-kpi-card {
  min-width: 0;
  min-height: 96px;

  display: flex;
  align-items: flex-start;

  gap: 8px;

  padding:
    11px;

  border:
    1px solid rgba(167, 205, 222, 0.44);

  border-radius: 12px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.99),
      rgba(247, 250, 252, 0.98)
    );

  box-shadow:
    0 5px 14px
    rgba(47, 50, 59, 0.03);
}

.query-drawer-kpi-icon {
  width: 27px;
  height: 27px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  flex-shrink: 0;

  border-radius: 8px;

  background:
    rgba(46, 155, 203, 0.10);

  color: var(--blue);

  font-size: 11px;
  font-weight: 800;
}

.query-drawer-kpi-card > div {
  min-width: 0;

  display: flex;
  flex-direction: column;
}

.query-drawer-kpi-card small {
  color: var(--muted-soft);

  font-size: 6.8px;
  font-weight: 800;

  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.query-drawer-kpi-card strong {
  margin-top: 6px;

  overflow: hidden;

  color: var(--ink);

  font-size: 18px;
  line-height: 1.1;
  font-weight: 800;

  text-overflow: ellipsis;
  white-space: nowrap;
}

.query-drawer-kpi-card-wide strong {
  font-size: 10px;
  line-height: 1.35;

  white-space: normal;
}

.query-drawer-kpi-card > div > span {
  margin-top: 5px;

  color: var(--muted);

  font-size: 6.9px;
  line-height: 1.35;
}

.query-drawer-platform-counts {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

.query-drawer-platform-counts-panel {
  justify-content: flex-start;

  gap: 6px;

  min-height: 118px;

  padding:
    12px;
}

.query-drawer-platform-pill {
  display: inline-flex;
  align-items: center;

  min-height: 26px;

  padding:
    0 9px;

  border:
    1px solid rgba(41, 114, 169, 0.12);

  border-radius: 999px;

  background:
    rgba(41, 114, 169, 0.065);

  color: var(--blue);

  font-size: 7.5px;
  font-weight: 750;
}

.query-drawer-context-copy {
  padding:
    12px;
}

.query-drawer-context-copy p {
  color: var(--ink-soft);

  font-size: 8.5px;
  line-height: 1.55;
}

.query-drawer-context-copy span {
  display: block;

  margin-top: 8px;

  padding:
    8px 9px;

  border-radius: 8px;

  background:
    rgba(46, 155, 203, 0.07);

  color: var(--muted);

  font-size: 7.5px;
  line-height: 1.5;
}


/* EMPTY / PLACEHOLDERS */

.query-drawer-empty {
  grid-column:
    1 / -1;

  min-height: 250px;

  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;

  gap: 5px;

  padding: 28px;

  border:
    1px dashed rgba(167, 205, 222, 0.72);

  border-radius: 12px;

  background:
    rgba(247, 250, 252, 0.66);

  text-align: center;
}

.query-drawer-empty-icon,
.query-drawer-placeholder-icon {
  width: 38px;
  height: 38px;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  margin-bottom: 3px;

  border-radius: 11px;

  background:
    rgba(46, 155, 203, 0.10);

  color: var(--blue);

  font-size: 15px;
  font-weight: 800;
}

.query-drawer-empty strong {
  color: var(--ink-soft);

  font-size: 10px;
  font-weight: 800;
}

.query-drawer-empty > span:not(.query-drawer-empty-icon) {
  max-width: 360px;

  color: var(--muted-soft);

  font-size: 8.5px;
  line-height: 1.5;
}

.query-drawer-placeholder {
  min-height: 420px;

  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;

  padding: 42px;

  border:
    1px solid rgba(167, 205, 222, 0.46);

  border-radius: 14px;

  background:
    linear-gradient(
      145deg,
      rgba(255, 255, 255, 0.98),
      rgba(247, 250, 252, 0.94)
    );

  text-align: center;
}

.query-drawer-placeholder h3 {
  margin-top: 2px;

  color: var(--ink);

  font-family:
    "Playfair Display",
    serif;

  font-size: 20px;
}

.query-drawer-placeholder p {
  max-width: 520px;

  margin-top: 7px;

  color: var(--muted);

  font-size: 9.5px;
  line-height: 1.65;
}


/* RESPONSIVE */

@media (max-width: 1180px) {
  .query-drawer {
    width: 88%;
  }

  .query-drawer-live-grid {
    grid-template-columns:
      minmax(0, 1fr)
      minmax(260px, 0.68fr);
  }

  .query-drawer-kpi-grid {
    grid-template-columns:
      1fr;
  }
}


@media (max-width: 920px) {
  .query-drawer {
    width: 94%;
  }

  .query-drawer-live-grid {
    grid-template-columns:
      1fr;
  }

  .query-drawer-kpi-grid {
    grid-template-columns:
      repeat(2, minmax(0, 1fr));
  }

  .query-drawer-commandbar {
    align-items: flex-start;
    flex-direction: column;
  }
}


@media (max-width: 700px) {
  .query-drawer {
    width: 100%;
  }

  .query-drawer-header {
    min-height: auto;

    padding:
      14px 14px 12px;
  }

  .query-drawer-title-row h2 {
    font-size: 20px;

    white-space: normal;
  }

  .query-drawer-title-copy p {
    white-space: normal;
  }

  .query-drawer-commandbar {
    padding:
      7px 14px;
  }

  .query-drawer-command-note {
    display: none;
  }

  .query-drawer-tabs {
    padding-left: 10px;
    padding-right: 10px;
  }

  .query-drawer-content {
    padding:
      10px;
  }

  .query-drawer-posts {
    grid-template-columns:
      1fr;
  }

  .query-drawer-kpi-grid {
    grid-template-columns:
      1fr;
  }

  .query-drawer-placeholder {
    min-height: 330px;

    padding:
      26px 18px;
  }
}


@media (max-width: 460px) {
  .query-drawer-query-mark {
    display: none;
  }

  .query-drawer-heading-topline {
    flex-wrap: wrap;
  }

  .query-drawer-panel-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .query-drawer-post-head,
  .query-drawer-post-footer {
    align-items: flex-start;
    flex-direction: column;
  }
}

