function quoteTerm(term) {
return (
'"' +
String(term)
.replace(/\\/g, '\\\\')
.replace(/"/g, '\\"') +
'"'
);
}

function buildGroupFormula(group) {
if (
!group ||
group.include.length === 0
) {
return '';
}

var includeFormula = group.include
.map(quoteTerm)
.join(' OR ');

if (
group.include.length > 1
) {
includeFormula =
'(' +
includeFormula +
')';
}

var parts = [
includeFormula
];

group.and.forEach(function (term) {
parts.push(
'AND ' +
quoteTerm(term)
);
});

group.and_not.forEach(function (term) {
parts.push(
'AND NOT ' +
quoteTerm(term)
);
});

return parts.join(' ');
}

function buildFormula() {
var formulas = groups
.map(buildGroupFormula)
.filter(function (formula) {
return formula !== '';
});

if (
formulas.length === 0
) {
return '';
}

if (
formulas.length === 1
) {
return formulas[0];
}

return formulas
.map(function (formula) {
return (
'(' +
formula +
')'
);
})
.join(' OR ');
}

function getTotalTerms() {
return groups.reduce(
function (total, group) {
return (
total +
group.include.length +
group.and.length +
group.and_not.length
);
},
0
);
}

function hasValidManualRules() {
if (groups.length === 0) {
return false;
}

return groups.every(function (group) {
return group.include.length > 0;
});
}

function getSelectableTargets() {
