function getValidSelectedTargetIds() {
var availableIds = getSelectableTargets().map(function (target) {
return String(target.id);
});

return selectedTargetIds.filter(function (id) {
return availableIds.indexOf(String(id)) !== -1;
});
}

function getSelectedTargets() {
var validIds = getValidSelectedTargetIds();

return getTargets().filter(function (target) {
return (
target &&
validIds.indexOf(String(target.id)) !== -1
);
});
}

function hasValidSources() {
return (
getValidSelectedTargetIds().length > 0 ||
useWeb
);
}

function hasValidPreview() {
return (
hasValidManualRules() &&
buildFormula() !== '' &&
hasValidSources()
);
}

