function formatDrawerDateTime(value) {
if (!value) {
return '—';
}

try {
return new Intl.DateTimeFormat(
'es-MX',
{
day: '2-digit',
month: '2-digit',
year: 'numeric',
hour: '2-digit',
minute: '2-digit'
}
).format(
new Date(value)
);
}
catch (error) {
return '—';
}
}

function formatDrawerMetric(value) {
if (
value === null ||
value === undefined ||
value === ''
) {
return '—';
}

var number = Number(value);

if (!isFinite(number)) {
return '—';
}

try {
return new Intl.NumberFormat(
'es-MX'
).format(number);
}
catch (error) {
return String(number);
}
}

function getDrawerLatestObservedAt(posts) {
var latest = null;

posts.forEach(function (post) {
var candidate =
post &&
(
post.metrics_last_observed_at ||
post.metrics_fetched_at ||
post.scraped_at ||
post.last_confirmed_at ||
post.matched_at
);

if (!candidate) {
return;
}

var time =
new Date(candidate).getTime();

if (
!isNaN(time) &&
(
latest === null ||
time > latest
)
) {
latest = time;
}
});

return (
latest === null
? null
: new Date(latest).toISOString()
);
}

function getDrawerPlatformCounts(posts) {
var counts = {};

posts.forEach(function (post) {
var platform =
String(
post &&
post.platform ||
''
)
.trim()
.toLowerCase();

if (!platform) {
platform =
'sin_plataforma';
}

counts[platform] =
(counts[platform] || 0) + 1;
});

var preferredOrder = [
'facebook',
'instagram',
'threads'
];

return Object.keys(counts)
.sort(function (a, b) {
var indexA =
preferredOrder.indexOf(a);

var indexB =
preferredOrder.indexOf(b);

if (
indexA === -1 &&
indexB === -1
) {
return a.localeCompare(
b,
'es',
{
sensitivity: 'base'
}
);
}

if (indexA === -1) {
return 1;
}

if (indexB === -1) {
return -1;
}

return indexA - indexB;
})
.map(function (platform) {
return {
platform: platform,
count: counts[platform]
};
});
}

