function renderDrawerBarRows(items, options) {
options = options || {};

if (!items.length) {
return (
'<div class="drawer-empty-inline">' +
'Sin datos disponibles.' +
'</div>'
);
}

var maxValue =
Math.max.apply(
null,
items.map(function (item) {
return Number(
item.value !== undefined
? item.value
: item.count || 0
);
})
) || 1;

return (
'<div class="drawer-bar-list">' +

items.map(function (item) {
var raw =
Number(
item.value !== undefined
? item.value
: item.count || 0
);

var width =
Math.max(
3,
Math.min(
100,
(raw / maxValue) * 100
)
);

var formatted =
options.formatValue
? options.formatValue(raw)
: formatDrawerMetric(raw);

return (
'<div class="drawer-bar-row">' +

'<div class="drawer-bar-row-head">' +
'<span>' +
escapeHtml(
item.label ||
item.key ||
''
) +
'</span>' +

'<strong>' +
escapeHtml(formatted) +
'</strong>' +
'</div>' +

'<div class="drawer-bar-track">' +
'<span class="drawer-bar-fill" style="width:' +
escapeHtml(
width.toFixed(2)
) +
'%"></span>' +
'</div>' +

'</div>'
);
}).join('') +

'</div>'
);
}

function renderDrawerChipCloud(items) {
