var last =
sortedPosts.length
? formatDrawerDateTime(
sortedPosts[
sortedPosts.length - 1
].published_at
)
: '—';

var topDay =
activity.days
.slice()
.sort(function (a, b) {
return b.count - a.count;
})[0];

var topHour =
activity.hours[0];

