query.status ||
'active'
).toLowerCase();

statusElement.textContent =
status === 'inactive'
? 'Inactiva'
: 'Activa';

statusElement.classList.toggle(
'inactive',
status === 'inactive'
);
}

if (formulaElement) {
formulaElement.textContent =
String(
query &&
query.formula_text ||
''
);
}

if (countElement) {
countElement.textContent =
String(
posts.length
);
}

if (observedElement) {
observedElement.textContent =
formatDrawerDateTime(
getDrawerLatestObservedAt(
posts
)
);
}

if (platformCountsElement) {
var counts =
getDrawerPlatformCounts(
posts
);

platformCountsElement.innerHTML =
counts.length
? counts.map(function (item) {
return (
'<span class="query-drawer-platform-pill">' +
escapeHtml(
formatPlatformLabel(
item.platform
)
) +
' · ' +
escapeHtml(
item.count
) +
'</span>'
);
}).join('')
: (
'<span class="query-drawer-platform-pill">' +
'Sin resultados' +
'</span>'
);
}

if (postsElement) {
if (
posts.length === 0
) {
postsElement.innerHTML =
'<div class="query-drawer-empty">' +
'<strong>Sin resultados activos</strong>' +
'<span>La consulta no tiene publicaciones coincidentes disponibles en este momento.</span>' +
'</div>';
}
else {
postsElement.innerHTML =
posts
.map(
renderDrawerPost
)
.join('');
}
}

renderDrawerAnalysisSections(
