);

setDrawerSection(
drawerState.activeSection ||
'live'
);
}

function openQueryDrawer(query) {
var overlay =
document.getElementById(
'queryDrawerOverlay'
);

if (!overlay) {
return;
}

drawerState.open = true;
drawerState.activeSection =
'live';

ensureDrawerRuntimeFixes();

overlay.hidden = false;

overlay.setAttribute(
'aria-hidden',
'false'
);

renderQueryDrawer();

setDrawerSection(
'live'
);

document.body.classList.add(
'query-drawer-open'
);

requestAnimationFrame(function () {
if (!drawerState.open) {
return;
}

overlay.classList.add(
'open'
);

